n": 1, "end": 947, "src": "W", "drop": [], "start": 867}, {"n": 1, "end": 1125, "src": "W", "drop": [[1008, 1017]], "start": 948}, {"n": 1, "end": 1217, "src": "W", "drop": [[1156, 1164], [1208, 1216]], "start": 1126}], "attribution": {"url": "https://en.wikipedia.org/w/index.php?title=Nysa_Bridge&oldid=1218679815", "title": "Nysa Bridge", "changes": "sentences selected and shortened", "licence_url": "https://creativecommons.org/licenses/by-sa/4.0/"}, "desc_sha256": "ac7f113ae8d5deb2197233b8a88d3d909b8cd181c6861e7268d59c2ff1b18605"}}', 'teaser-prov-s035-rollback:e62c980a-351d-40c1-8297-05f52f72a59c:raw_data', 'rollback of teaser-prov-s035: raw_data ''{"_card_provenance": {"v": 2, "ai": "generated", "run": "wb-ws-2026-09-27-04", "kind": "teaser", "lane": "WB", "check": {"at": "2026-09-29T19:55:47+00:00", "by": "teaser-wb-ws-2026-09-27-04-check-028", "stage": "check", "claims": [{"claim": "the Nysa Bridge spans the Cakircak stream", "support": ["S1", "S6"]}, {"claim": "it lies in ancient Caria", "support": ["S1"]}, {"claim": "it is a Roman bridge/vault", "support": ["S1", "S7"]}, {"claim": "it runs some 100 m", "support": ["S2", "S6"]}, {"claim": "it looks like a tunnel", "support": ["S6"]}, {"claim": "it is built entirely above ground", "support": ["S6"]}, {"claim": "it is a vault", "support": ["S4", "S7"]}, {"claim": "it carries the area in front of the city theatre", "support": ["S3"]}], "verdict": "PASS"}, "verify": {"at": "2026-09-29T21:37:35+00:00", "by": "teaser-wb-ws-2026-09-27-04-verify-082", "stage": "verify", "claims": 10, "verdict": "VERIFIED", "unproven": 0, "text_sha256": "793f535abcd7286dac87de24db888a9afb6a46dc4c90aa657e6696c10d9aa3ba"}, "ai_system": "Claude Opus (Anthropic): anthropic/claude-opus-5-5 (Claude Code agent), an-sites-remediation-2026-09", "web_facts": [], "desc_sha256": "ac7f113ae8d5deb2197233b8a88d3d909b8cd181c6861e7268d59c2ff1b18605", "text_sha256": "793f535abcd7286dac87de24db888a9afb6a46dc4c90aa657e6696c10d9aa3ba"}, "description_citati